<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/**
 * `transfers_comms` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $ID
 * @property int|null $TransferID
 * @property string|null $Notes
 * @property Carbon|null $CreatedDate
 * @property string|null $CreatedBy
 */
class TransfersComm extends Model
{
    protected $table = 'transfers_comms';

    protected $primaryKey = 'ID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'ID' => 'integer',
            'TransferID' => 'integer',
            'CreatedDate' => 'datetime',
        ];
    }

    protected static function booted(): void
    {
        // PHPRunner's add event: created now, by the logged-in user.
        static::creating(function (TransfersComm $comm): void {
            $comm->CreatedDate = now();
            $comm->CreatedBy = (string) auth()->user()?->username;
        });
    }

    public function transfer(): BelongsTo
    {
        return $this->belongsTo(Transfer::class, 'TransferID', 'TransferID');
    }
}
